<?php require_once __DIR__.'/../config.php'; if(!isset($_SESSION['admin_id'])){header('Location: /admin/login.php');exit;} 
$file=__DIR__.'/../config/bot_settings.json'; $saved='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $data=['telegram_key'=>clean_input($_POST['telegram_key']??''),'whatsapp_key'=>clean_input($_POST['whatsapp_key']??''),'auto_reply'=>clean_input($_POST['auto_reply']??'')]; file_put_contents($file,json_encode($data,JSON_PRETTY_PRINT)); $saved='Saved'; }
$current=file_exists($file)?json_decode(file_get_contents($file),true):['telegram_key'=>'','whatsapp_key'=>'','auto_reply'=>''];
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 p-4"><h1 class="font-bold text-xl mb-3">Bot Settings</h1><form method="post" class="bg-white rounded-xl p-4 shadow space-y-2"><input name="telegram_key" value="<?=clean_input($current['telegram_key'])?>" class="w-full border p-2 rounded" placeholder="Telegram API key"><input name="whatsapp_key" value="<?=clean_input($current['whatsapp_key'])?>" class="w-full border p-2 rounded" placeholder="WhatsApp API key"><textarea name="auto_reply" class="w-full border p-2 rounded" placeholder="Auto-reply template"><?=clean_input($current['auto_reply'])?></textarea><button class="bg-indigo-600 text-white px-4 py-2 rounded">Save</button><span class="text-emerald-600"><?=$saved?></span></form></body></html>
